(function() {
    function initToggle(root) {
        if (!root || root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        var toggleBtn = root.querySelector('.sl-toggle-switch');
        var labelMonthly = root.querySelector('.sl-label-monthly');
        var labelYearly = root.querySelector('.sl-label-yearly');
        var statusEl = root.querySelector('.sl-toggle-status');
        var monthlyPrices = root.querySelectorAll('.sl-price-monthly');
        var yearlyPrices = root.querySelectorAll('.sl-price-yearly');
        if (!toggleBtn) return;

        function setBilling(isYearly) {
            toggleBtn.setAttribute('aria-checked', isYearly ? 'true' : 'false');
            root.classList.toggle('is-yearly', isYearly);

            monthlyPrices.forEach(function(el) {
                if (isYearly) {
                    el.setAttribute('hidden', '');
                } else {
                    el.removeAttribute('hidden');
                }
            });
            yearlyPrices.forEach(function(el) {
                if (isYearly) {
                    el.removeAttribute('hidden');
                } else {
                    el.setAttribute('hidden', '');
                }
            });

            if (labelMonthly) labelMonthly.classList.toggle('inactive', isYearly);
            if (labelYearly) labelYearly.classList.toggle('inactive', !isYearly);
            if (statusEl) {
                statusEl.textContent = isYearly ? 'Showing yearly billing prices.' : 'Showing monthly billing prices.';
            }
        }

        setBilling(false);

        toggleBtn.addEventListener('click', function() {
            var isCurrentlyYearly = toggleBtn.getAttribute('aria-checked') === 'true';
            setBilling(!isCurrentlyYearly);
        });

        if (labelMonthly) {
            labelMonthly.addEventListener('click', function() {
                if (root.querySelector('[data-sl-edit-id]')) return;
                setBilling(false);
            });
        }
        if (labelYearly) {
            labelYearly.addEventListener('click', function() {
                if (root.querySelector('[data-sl-edit-id]')) return;
                setBilling(true);
            });
        }
    }

    function initAll() {
        document.querySelectorAll('.sl-pricing-toggle').forEach(initToggle);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
